/**
 * HMAC-SHA256 (RFC 2104) built on the from-scratch SHA-256 in ./sha256.mjs.
 *
 * HMAC(K, m) = H( (K' ^ opad) || H( (K' ^ ipad) || m ) )
 *
 *   K'   = K hashed down to 32 bytes when len(K) > blockSize, otherwise K
 *          right-padded with zero bytes up to blockSize (64).
 *   ipad = 0x36 repeated blockSize times
 *   opad = 0x5c repeated blockSize times
 *
 * No platform primitives of any kind are used here: every byte comes out of the
 * hand-written compression function in ./sha256.mjs.
 */

import { sha256, SHA256_BLOCK_SIZE, SHA256_DIGEST_SIZE } from './sha256.mjs';
import { utf8Encode } from './bytes.mjs';

/** RFC 2104 inner pad byte. */
const IPAD_BYTE = 0x36;

/** RFC 2104 outer pad byte. */
const OPAD_BYTE = 0x5c;

/**
 * Coerce an input into a Uint8Array of bytes.
 *
 * Uint8Array passes straight through; other array-likes / ArrayBuffers are
 * wrapped; strings are UTF-8 encoded (python-jose accepts str keys and encodes
 * them as UTF-8 before signing, so this keeps the same behaviour).
 *
 * @param {Uint8Array|ArrayBuffer|Array<number>|string} value
 * @param {string} label Name used in the error message.
 * @returns {Uint8Array}
 */
function toBytes(value, label) {
  if (value instanceof Uint8Array) {
    return value;
  }
  if (typeof value === 'string') {
    return utf8Encode(value);
  }
  if (value instanceof ArrayBuffer) {
    return new Uint8Array(value);
  }
  if (Array.isArray(value)) {
    return new Uint8Array(value);
  }
  throw new TypeError(`${label} must be a Uint8Array or a string`);
}

/**
 * Normalise a key to exactly SHA256_BLOCK_SIZE bytes.
 *
 * Keys longer than the block size are hashed first (RFC 2104: "keys longer than
 * B bytes are first hashed using H"); shorter keys are zero padded on the right.
 *
 * @param {Uint8Array} keyBytes
 * @returns {Uint8Array} A fresh block-sized buffer.
 */
function normalizeKey(keyBytes) {
  const block = new Uint8Array(SHA256_BLOCK_SIZE);
  if (keyBytes.length > SHA256_BLOCK_SIZE) {
    block.set(sha256(keyBytes), 0);
  } else {
    block.set(keyBytes, 0);
  }
  return block;
}

/**
 * Compute HMAC-SHA256.
 *
 * @param {Uint8Array|string} keyBytes Secret key (raw bytes, or a string that
 *   will be UTF-8 encoded).
 * @param {Uint8Array|string} messageBytes Message to authenticate.
 * @returns {Uint8Array} The 32-byte tag.
 */
export function hmacSha256(keyBytes, messageBytes) {
  const key = normalizeKey(toBytes(keyBytes, 'key'));
  const message = toBytes(messageBytes, 'message');

  // (K' ^ ipad) || message  -> inner hash
  const innerInput = new Uint8Array(SHA256_BLOCK_SIZE + message.length);
  for (let i = 0; i < SHA256_BLOCK_SIZE; i += 1) {
    innerInput[i] = key[i] ^ IPAD_BYTE;
  }
  innerInput.set(message, SHA256_BLOCK_SIZE);
  const innerDigest = sha256(innerInput);

  // (K' ^ opad) || innerDigest  -> outer hash == the tag
  const outerInput = new Uint8Array(SHA256_BLOCK_SIZE + SHA256_DIGEST_SIZE);
  for (let i = 0; i < SHA256_BLOCK_SIZE; i += 1) {
    outerInput[i] = key[i] ^ OPAD_BYTE;
  }
  outerInput.set(innerDigest, SHA256_BLOCK_SIZE);

  return sha256(outerInput);
}

/**
 * Compare two byte arrays without leaking *where* they differ.
 *
 * The length is checked up front (like Python's hmac.compare_digest, which also
 * returns False immediately for differing lengths); equal-length inputs are then
 * compared by accumulating the XOR of every byte pair so the loop always runs to
 * completion and the running time does not depend on the contents.
 *
 * @param {Uint8Array} a
 * @param {Uint8Array} b
 * @returns {boolean} True when both arrays hold the same bytes.
 */
export function constantTimeEqual(a, b) {
  if (!(a instanceof Uint8Array) || !(b instanceof Uint8Array)) {
    return false;
  }
  if (a.length !== b.length) {
    return false;
  }
  let diff = 0;
  for (let i = 0; i < a.length; i += 1) {
    diff |= a[i] ^ b[i];
  }
  return diff === 0;
}

// SCRATCH ONLY (not part of /output): independent FIPS 180-4 SHA-256 used to
// validate hmac.mjs before the real ./sha256.mjs exists.
export const SHA256_BLOCK_SIZE = 64;
export const SHA256_DIGEST_SIZE = 32;

const K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

const rotr = (x, n) => ((x >>> n) | (x << (32 - n))) >>> 0;

export function sha256(bytes) {
  let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
  let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;

  const len = bytes.length;
  const bitLen = len * 8;
  const padLen = ((len % 64) < 56 ? 56 - (len % 64) : 120 - (len % 64));
  const total = len + padLen + 8;
  const msg = new Uint8Array(total);
  msg.set(bytes, 0);
  msg[len] = 0x80;
  // 64-bit big-endian bit length (len * 8 stays exact for our sizes)
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  msg[total - 8] = (hi >>> 24) & 0xff;
  msg[total - 7] = (hi >>> 16) & 0xff;
  msg[total - 6] = (hi >>> 8) & 0xff;
  msg[total - 5] = hi & 0xff;
  msg[total - 4] = (lo >>> 24) & 0xff;
  msg[total - 3] = (lo >>> 16) & 0xff;
  msg[total - 2] = (lo >>> 8) & 0xff;
  msg[total - 1] = lo & 0xff;

  const w = new Uint32Array(64);
  for (let off = 0; off < total; off += 64) {
    for (let t = 0; t < 16; t += 1) {
      const i = off + t * 4;
      w[t] = ((msg[i] << 24) | (msg[i + 1] << 16) | (msg[i + 2] << 8) | msg[i + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t += 1) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
    for (let t = 0; t < 64; t += 1) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0; h5 = (h5 + f) >>> 0; h6 = (h6 + g) >>> 0; h7 = (h7 + h) >>> 0;
  }

  const out = new Uint8Array(32);
  [h0, h1, h2, h3, h4, h5, h6, h7].forEach((v, i) => {
    out[i * 4] = (v >>> 24) & 0xff;
    out[i * 4 + 1] = (v >>> 16) & 0xff;
    out[i * 4 + 2] = (v >>> 8) & 0xff;
    out[i * 4 + 3] = v & 0xff;
  });
  return out;
}

// SCRATCH ONLY (not part of /output): minimal stand-in for ./bytes.mjs.
export function utf8Encode(str) {
  const out = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return new Uint8Array(out);
}

// SCRATCH ONLY: RFC 4231 + RFC 2104 checks for /output/lib/hmac.mjs
import { sha256 } from './hmac_scratch_sha256.mjs';
import { utf8Encode } from './hmac_scratch_bytes.mjs';
import { hmacSha256, constantTimeEqual } from './hmac_under_test.mjs';

const hex = (b) => Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');
const unhex = (s) => new Uint8Array(s.match(/../g).map((h) => parseInt(h, 16)));
const rep = (byte, n) => new Uint8Array(n).fill(byte);

let fails = 0;
function check(name, got, want) {
  const ok = got === want;
  if (!ok) fails += 1;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}`);
  if (!ok) console.log(`   got  ${got}\n   want ${want}`);
}

// --- sanity: my scratch SHA-256 itself (FIPS 180-4 examples) ---
check('sha256("")', hex(sha256(new Uint8Array(0))),
  'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');
check('sha256("abc")', hex(sha256(utf8Encode('abc'))),
  'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
check('sha256(896-bit msg)', hex(sha256(utf8Encode(
  'abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'))),
  '248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1');

// --- RFC 4231 HMAC-SHA-256 test cases 1..7 ---
check('RFC4231 #1', hex(hmacSha256(rep(0x0b, 20), utf8Encode('Hi There'))),
  'b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7');

check('RFC4231 #2', hex(hmacSha256(utf8Encode('Jefe'), utf8Encode('what do ya want for nothing?'))),
  '5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843');

check('RFC4231 #3', hex(hmacSha256(rep(0xaa, 20), rep(0xdd, 50))),
  '773ea91e36800e46854db8ebd09181a72959098b3ef8c122d9635514ced565fe');

check('RFC4231 #4', hex(hmacSha256(unhex('0102030405060708090a0b0c0d0e0f10111213141516171819'), rep(0xcd, 50))),
  '82558a389a443c0ea4cc819899f2083a85f0faa3e578f8077a2e3ff46729665b');

// #5 is a truncated (128-bit) tag: compare the first 16 bytes
check('RFC4231 #5 (trunc-128)',
  hex(hmacSha256(rep(0x0c, 20), utf8Encode('Test With Truncation')).slice(0, 16)),
  'a3b6167473100ee06e0c796c2955552b');

// #6 / #7: 131-byte key -> longer than the 64-byte block, must be pre-hashed
check('RFC4231 #6 (131-byte key)',
  hex(hmacSha256(rep(0xaa, 131), utf8Encode('Test Using Larger Than Block-Size Key - Hash Key First'))),
  '60e431591ee0b67f0d8a26aacbf5b77f8e0bc6213728c5140546040f0ee37f54');

check('RFC4231 #7 (131-byte key, long msg)',
  hex(hmacSha256(rep(0xaa, 131), utf8Encode(
    'This is a test using a larger than block-size key and a larger than block-size data.'
    + ' The key needs to be hashed before being used by the HMAC algorithm.'))),
  '9b09ffa71b942fcb27635fbcd5b0e944bfdc63644f0713938a7f51535c3a35e2');

// --- boundary key lengths: 63 / 64 / 65 bytes (65 must be pre-hashed) ---
// Reference values are derived from the RFC 2104 definition applied by hand
// using the scratch SHA-256 (independent of hmac.mjs' own code path).
function referenceHmac(key, msg) {
  let k = key;
  if (k.length > 64) k = sha256(k);
  const kp = new Uint8Array(64);
  kp.set(k, 0);
  const inner = new Uint8Array(64 + msg.length);
  const outer = new Uint8Array(64 + 32);
  for (let i = 0; i < 64; i += 1) {
    inner[i] = kp[i] ^ 0x36;
    outer[i] = kp[i] ^ 0x5c;
  }
  inner.set(msg, 64);
  outer.set(sha256(inner), 64);
  return sha256(outer);
}
for (const n of [0, 1, 55, 56, 63, 64, 65, 100, 200]) {
  const key = rep(0x5a, n);
  const msg = utf8Encode('boundary-' + n);
  check(`key length ${n}`, hex(hmacSha256(key, msg)), hex(referenceHmac(key, msg)));
}

// --- message length sweep across SHA-256 padding boundaries ---
for (const n of [0, 1, 54, 55, 56, 63, 64, 65, 119, 120, 127, 128, 1000]) {
  const msg = new Uint8Array(n);
  for (let i = 0; i < n; i += 1) msg[i] = (i * 37 + 11) & 0xff;
  check(`msg length ${n}`, hex(hmacSha256(utf8Encode('secret'), msg)), hex(referenceHmac(utf8Encode('secret'), msg)));
}

// --- string inputs are UTF-8 encoded (convenience path) ---
check('string key == utf8 bytes key',
  hex(hmacSha256('secret', 'héllo😀')),
  hex(hmacSha256(utf8Encode('secret'), utf8Encode('héllo😀'))));

// --- inputs are not mutated ---
const k0 = rep(0x0b, 20);
const m0 = utf8Encode('Hi There');
hmacSha256(k0, m0);
check('key not mutated', hex(k0), hex(rep(0x0b, 20)));
check('msg not mutated', hex(m0), hex(utf8Encode('Hi There')));

// --- constantTimeEqual ---
check('cte equal', String(constantTimeEqual(unhex('00ff10'), unhex('00ff10'))), 'true');
check('cte differ last', String(constantTimeEqual(unhex('00ff10'), unhex('00ff11'))), 'false');
check('cte differ first', String(constantTimeEqual(unhex('01ff10'), unhex('00ff10'))), 'false');
check('cte length mismatch', String(constantTimeEqual(unhex('00ff'), unhex('00ff10'))), 'false');
check('cte both empty', String(constantTimeEqual(new Uint8Array(0), new Uint8Array(0))), 'true');
check('cte high-bit bytes', String(constantTimeEqual(unhex('80'), unhex('80'))), 'true');
check('cte 0x80 vs 0x00', String(constantTimeEqual(unhex('80'), unhex('00'))), 'false');
check('cte non-array', String(constantTimeEqual(null, unhex('00'))), 'false');

console.log(fails === 0 ? '\nALL PASS' : `\n${fails} FAILURES`);
if (fails) process.exitCode = 1;

// SCRATCH ONLY: end-to-end check — recompute the reference executable's JWS
// signature with hmacSha256 and compare against the emitted token.
import { hmacSha256, constantTimeEqual } from './hmac_under_test.mjs';
import { utf8Encode } from './hmac_scratch_bytes.mjs';

const ALPHA = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
function b64url(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = bytes[i + 1];
    const b2 = bytes[i + 2];
    out += ALPHA[b0 >> 2];
    out += ALPHA[((b0 & 0x03) << 4) | ((b1 === undefined ? 0 : b1) >> 4)];
    if (b1 === undefined) break;
    out += ALPHA[((b1 & 0x0f) << 2) | ((b2 === undefined ? 0 : b2) >> 6)];
    if (b2 === undefined) break;
    out += ALPHA[b2 & 0x3f];
  }
  return out;
}

const tokens = process.argv.slice(2);
let fails = 0;
for (const token of tokens) {
  const idx = token.lastIndexOf('.');
  const signingInput = token.slice(0, idx);
  const wantSig = token.slice(idx + 1);
  const gotSig = b64url(hmacSha256(utf8Encode('secret'), utf8Encode(signingInput)));
  const ok = gotSig === wantSig
    && constantTimeEqual(hmacSha256('secret', signingInput), hmacSha256(utf8Encode('secret'), utf8Encode(signingInput)));
  if (!ok) fails += 1;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${signingInput.slice(0, 40)}...`);
  if (!ok) console.log(`   got  ${gotSig}\n   want ${wantSig}`);
}
console.log(fails === 0 ? 'ALL PASS' : `${fails} FAILURES`);
if (fails) process.exitCode = 1;

